CREATED_B64 = {'backend/app/services/vision_app/camera_resource_runtime.py': '', 'backend/app/services/vision_app/frame_slot_store.py': '', 'backend/app/services/vision_app/workspace_runtime.py': '', 'backend/tests/vision_app/test_vision_app_v1300.py': '', 'frontend/docs/llm_context/updates/v1300_multicamera_workspaces_simulator.md': '', 'frontend/src/components/ComputerVision/CameraDeclarationWorkspace.tsx': '', 'frontend/src/components/ComputerVision/DeveloperSimulatorWorkspace.tsx': '', 'frontend/src/components/ComputerVision/WorkspaceTabs.tsx': ''}

MODIFIED = {
    path: {
        "old": base64.b64decode(payload["old"]).decode("utf-8"),
        "new": base64.b64decode(payload["new"]).decode("utf-8"),
    }
    for path, payload in MODIFIED_B64.items()
}
CREATED = {
    path: base64.b64decode(payload).decode("utf-8")
    for path, payload in CREATED_B64.items()
}


def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()

    fe_candidates = []
    be_candidates = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    be_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            p for p in fe_candidates
            if (p / "src/Pages/ComputerVisionPage.tsx").exists()
            and (p / "src/components/ComputerVision/AutomationIdeWorkspace.tsx").exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (p / "app/services/vision_app/automation_manager.py").exists()
            and (p / "app/services/vision_app/models.py").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )
    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/"):]
    raise ValueError(virtual)


def modified_state(path: Path, old: str, new: str) -> str:
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def created_state(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    if path.read_text(encoding="utf-8") == desired:
        return "OK"
    return "CONFLICT"


def scan(frontend: Path, backend: Path):
    print("=" * 112)
    print("COMPUTER VISION V0.13.0 — MULTI-CAMERA / MULTI-WORKSPACE / ONLINE / SIMULATOR")
    print("=" * 112)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    conflicts = 0

    for virtual, payload in MODIFIED.items():
        state = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        print(f"  [{state:12}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            conflicts += 1

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        print(f"  [{state:12}] {virtual}")
        if state == "CONFLICT":
            conflicts += 1

    print()
    print("v0.13 contract:")
    print("  Program v5: declared IOT resources + declared Camera resources + Workspaces")
    print("  Camera drivers: Basler | HTTP/Raspberry Pi | Simulated")
    print("  Camera slots: Current_image + Streaming_frame")
    print("  Workspace owns Master + Working and binds to one image slot")
    print("  Endpoint Registry adds camera.* and workspace.* live objects")
    print("  system.run_inspection() = active workspace; workspace.<alias>.run_inspection() = explicit")
    print("  workspace.<alias>.activate() changes backend active workspace and UI follows")
    print("  Typed IntelliSense hints: ON/OFF vs OK/NG/NONE + units/object types")
    print("  Top-level ONLINE/OFFLINE arms/disarms Automation scheduler")
    print("  Developer Simulator uses the same declared device/camera object contracts")
    print("  Streaming v1 is engineering polling preview, not final soft-trigger transport")
    print("  Legacy camera/master/working/io fields remain mirrored for compatibility")
    print("  v0.13 LLM handoff + SYSTEM_*.md regeneration included")

    if conflicts:
        print()
        print(f"[WARN] {conflicts} conflict/base issue(s); apply will stop safely.")

    return 0


def preflight(frontend: Path, backend: Path):
    errors = []

    for virtual, payload in MODIFIED.items():
        state = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        if state not in {"UPDATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        if state not in {"CREATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    if errors:
        raise RuntimeError(
            "Safe update stopped:\n  - " + "\n  - ".join(errors)
        )


def backup(frontend: Path, backend: Path, paths: list[Path]) -> Path:
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = (
        frontend
        / ".lambda_updater_backups"
        / f"computer_vision_v1300_{stamp}"
    )
    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue
        try:
            rel = path.relative_to(frontend)
            destination = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            destination = root / "backend" / rel

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    return root


def regenerate_context(frontend: Path, backend: Path):
    generator = frontend / "tools/generate_llm_context_map.py"
    if not generator.exists():
        print("[SKIP] Context generator not found")
        return

    cmd = [
        sys.executable,
        str(generator),
        "--frontend",
        str(frontend),
        "--backend",
        str(backend),
    ]

    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd.extend(
            [
                "--output-dir",
                str(frontend / "docs/llm_context"),
            ]
        )

    proc = subprocess.run(
        cmd,
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )

    if proc.returncode != 0:
        raise RuntimeError(
            "Context generator failed:\n"
            + (proc.stdout + "\n" + proc.stderr).strip()
        )

    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    preflight(frontend, backend)

    targets = [
        real_path(frontend, backend, key)
        for key in list(MODIFIED) + list(CREATED)
    ]

    backup_root = backup(frontend, backend, targets)

    for virtual, payload in MODIFIED.items():
        path = real_path(frontend, backend, virtual)
        if path.read_text(encoding="utf-8") != payload["new"]:
            path.write_text(payload["new"], encoding="utf-8")
            print(f"[WRITE] {virtual}")

    for virtual, desired in CREATED.items():
        path = real_path(frontend, backend, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] {virtual}")

    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def python_syntax(backend: Path):
    failures = []
    files = []

    for virtual in list(MODIFIED) + list(CREATED):
        if virtual.startswith("backend/") and virtual.endswith(".py"):
            path = real_path(Path("/unused"), backend, virtual)
            files.append(path)
            try:
                py_compile.compile(str(path), doraise=True)
            except Exception as exc:
                failures.append(
                    f"{path.relative_to(backend)}: {exc}"
                )

    return len(files), failures


def typescript_transpile(frontend: Path):
    files = [
        real_path(frontend, Path("/unused"), virtual)
        for virtual in list(MODIFIED) + list(CREATED)
        if virtual.startswith("frontend/")
        and virtual.endswith((".ts", ".tsx"))
    ]

    code = r"""
const fs = require("fs");
const ts = require("typescript");
let failed = false;

for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (d) => d.category === ts.DiagnosticCategory.Error,
  );

  if (errors.length) {
    failed = true;
    console.error("TS_ERROR", file);
    for (const d of errors) {
      console.error(
        ts.flattenDiagnosticMessageText(d.messageText, "\n"),
      );
    }
  }
}

process.exit(failed ? 1 : 0);
"""

    env = dict(os.environ)
    npm_root = subprocess.run(
        ["npm", "root", "-g"],
        text=True,
        capture_output=True,
    )

    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (
            os.pathsep + env["NODE_PATH"]
            if env.get("NODE_PATH")
            else ""
        )

    return subprocess.run(
        ["node", "-e", code, *map(str, files)],
        cwd=str(frontend),
        env=env,
        text=True,
        capture_output=True,
    )


